$("#download_enter").on("click",function(){const n=$(this),t=n.data("check-url"),a=$('#download_form select[name="base_id"]').val(),o=$('#download_form input[name="date"]').val();if(!o){window.alert("ダウンロード年月を選択してください。");return}n.prop("disabled",!0),$.get(t,{base_id:a,date:o}).done(function(d){!d.is_submitted&&!window.confirm(`選択された年月の勤怠は、まだ提出（締め）されていません。
確定前のデータが出力されますが、ダウンロードしますか？`)||$("#download_form").submit()}).fail(function(){window.alert("提出状況の確認に失敗しました。時間をおいて再度お試しください。")}).always(function(){n.prop("disabled",!1)})});$("#download_data_enter").on("click",function(){$("#download_data_form").submit()});
